UPDATE orders SET last_check_at=0 WHERE provider='bachs' AND status IN ('pending','failed','underpaid','review','expired','cancelled') AND payment_code='method_mismatch' AND EXISTS (SELECT 1 FROM bachs_webhook_events AS event WHERE event.order_ref=orders.ref AND event.mode=orders.mode AND event.checkout_id=orders.provider_session AND event.event_type IN ('checkout.completed','collection.succeeded'));
